import React, { useState, useEffect } from 'react';
import { useHistory } from 'react-router-dom';
import './Header.css'; 

function Header() {
  const history = useHistory();
  const [user, setUser] = useState(null);

  useEffect(() => {
    const userString = localStorage.getItem('user');
    if (userString) {
      try {
        const parsedUser = JSON.parse(userString);
        setUser(parsedUser);
      } catch (error) {
        console.error("Error parsing user data:", error);
      }
    }
  }, []);

  const handleLogout = () => {
    localStorage.removeItem('token');
    localStorage.removeItem('user');
    setUser(null);
    history.push('/login');
  };

  return (
    <div className="headerParentDiv" style={{ backgroundColor: '#f8f9fa', padding: '10px 0', borderBottom: '1px solid #ddd' }}>
      <div className="headerChildDiv" style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', padding: '0 20px' }}>
        
        <h2 style={{ cursor: 'pointer', margin: 0, color: '#002f34' }} onClick={() => history.push('/')}>
          Thrift Shop
        </h2>
        
        <div style={{ display: 'flex', alignItems: 'center', gap: '15px' }}>
          {user ? (
            <div style={{ display: 'flex', alignItems: 'center', gap: '15px' }}>
              <span style={{ fontWeight: 'bold', color: '#002f34' }}>Welcome, {user.name}</span>
              <button 
                onClick={handleLogout} 
                style={{ padding: '8px 20px', cursor: 'pointer', fontWeight: 'bold', backgroundColor: 'transparent', border: '1px solid #002f34', color: '#002f34', borderRadius: '4px' }}
              >
                Logout
              </button>
            </div>
          ) : (
            <div>
              <button 
                onClick={() => history.push('/login')} 
                style={{ margin: '0 10px', padding: '8px 20px', cursor: 'pointer', fontWeight: 'bold', backgroundColor: 'transparent', border: 'none', textDecoration: 'underline', color: '#002f34' }}
              >
                Login
              </button>
              <button 
                onClick={() => history.push('/signup')} 
                style={{ padding: '8px 20px', cursor: 'pointer', fontWeight: 'bold', backgroundColor: '#002f34', color: 'white', borderRadius: '4px', border: 'none' }}
              >
                Signup
              </button>
            </div>
          )}

          <button 
            onClick={() => history.push(user ? '/create' : '/login')} 
            style={{ padding: '8px 20px', cursor: 'pointer', fontWeight: 'bold', backgroundColor: '#ffce32', color: '#002f34', borderRadius: '20px', border: '2px solid #002f34' }}
          >
            + SELL
          </button>
        </div>

      </div>
    </div>
  );
}

export default Header;
